+        .map_err(|error| format!("Failed to read from the terminal: {error}"))?;
+    let writer = pair
+        .master
+        .take_writer()
+        .map_err(|error| format!("Failed to write to the terminal: {error}"))?;
+    let killer = child.clone_killer();
